    LANGUAGE_WRAPPER = 'In a math contest, let n = {n}. Consider the polynomial P(x) = (1 + x + x^2 + ... + x^{n})^2 − x^{n}. Its 2n complex roots are written as z_k = r_k[cos(2π a_k) + i sin(2π a_k)] for k = 1, 2, ..., 2n, with 0 < a_1 ≤ a_2 ≤ ... ≤ a_{2n} < 1 and r_k > 0. Let S = a_1 + a_2 + ... + a_{t}, where t = {t}. Express S in lowest terms as m/q, and report the integer m + q.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose n moderately large to ensure nontrivial merging of two angle sequences.
# Prefer odd n to avoid duplicate angles, but allow some even n occasionally for variety.
candidates = [k for k in range(15, 61)]
rng.shuffle(candidates)
n = None
for k in candidates:
    # Bias toward odd n (about 2/3 chance)
    if k % 2 == 1 and rng.random() < 0.67:
        n = k
        break
if n is None:
    # Fallback to any number in range
    n = rng.randint(15, 60)
# Pick t to be reasonably sized but far from trivial
t_hi = min(18, 2*n - 2)
t_lo = 6
if t_hi < t_lo:
    t_hi = t_lo
t = rng.randint(t_lo, t_hi)
return {'n': n, 't': t}

