# Domain: ensure t does not exceed total number of roots 2n
total_roots = 2*n
if t > total_roots or t <= 0:
    return (False, None)
# Build the two angle lists as exact rationals (numerator, denominator)
A = [(j, n) for j in range(1, n)]            # j/n for j=1..n-1
